import{_ as r,a as o}from"./chunks/f317fe76446c1042a6a5.DVLTmT9J.js";import{_ as l,C as a,o as i,c as s,j as t,a as n,E as h,a5 as c}from"./chunks/framework.DNkHA0lr.js";const q=JSON.parse('{"title":"多数人都是迷失的（如何最快地毁掉你的人生）","description":"","frontmatter":{"title":"多数人都是迷失的（如何最快地毁掉你的人生）","originalTitle":"Most People Are Lost (How To Ruin Your Life, Fast)","date":"2024-03-01","originalUrl":"https://thedankoe.com/letters/most-people-are-lost-how-to-ruin-your-life-fast/","minutes":11,"sourceHash":"794cdc1615a3f43e0e921b14052d61cc9224cf4d1dab1470a3f9742cf57b16c3","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/most-people-are-lost-how-to-ruin-your-life-fast/"}]]},"headers":[],"relativePath":"letters/most-people-are-lost-how-to-ruin-your-life-fast.md","filePath":"letters/most-people-are-lost-how-to-ruin-your-life-fast.md"}'),u={name:"letters/most-people-are-lost-how-to-ruin-your-life-fast.md"};function g(f,p,d,m,_,b){const e=a("ArticleMeta");return i(),s("div",null,[p[0]||(p[0]=t("h1",{id:"多数人都是迷失的-如何最快地毁掉你的人生",tabindex:"-1"},[n("多数人都是迷失的（如何最快地毁掉你的人生） "),t("a",{class:"header-anchor",href:"#多数人都是迷失的-如何最快地毁掉你的人生","aria-label":'Permalink to "多数人都是迷失的（如何最快地毁掉你的人生）"'},"​")],-1)),h(e),p[1]||(p[1]=c('<p><a href="https://www.youtube.com/embed/QTpx8BcCnTg?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>毁掉你人生最快的方法：</p><p>按照别人希望你做的去做。</p><p>从不质疑别人告诉你的东西。</p><p>选择表面上看起来安全的路，而这条路其实最不安全。</p><p>回避生活的本质——试错——把自己封闭起来，拒绝深刻、深层、有意义的东西。</p><p>最大的错误，就是不犯任何错误。</p><p>这就是大众的生活。</p><p>在表面上蹦来蹦去。</p><p>只学习学校教的东西。</p><p>日复一日重复同一天。</p><p>打卡上班，打卡下班，然后用剩下的时间麻痹自己的大脑，不去想明天和明天之后会发生什么。</p><p>走出这种毫无意义生活的路，早已在你心中深处等着你了。</p><p>我们每个人都拥有通往「自然指南针」的入口。</p><h2 id="自然指南针" tabindex="-1">自然指南针 <a class="header-anchor" href="#自然指南针" aria-label="Permalink to &quot;自然指南针&quot;">​</a></h2><blockquote><p>如果你不知道自己想要什么，就会有人告诉你该想要什么，而你也会信以为真。<a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">——《专注的艺术》</a></p></blockquote><p>如何随心所欲地生活：</p><p>做你想做的事，但不要忽视你行为带来的后果。</p><p>你必须先去做你以为自己想要的事，才能意识到你不想要什么。你必须先去除你不想做的事，才能真正做到你想做的事。</p><p>要绝对确定地知道未来会发生什么，是不可能的。</p><p>这就是为什么大众都蜂拥去追求“稳定”的工作和信仰体系。</p><p>这是一种为了逃避挣扎而制造的确定性假象。你无法跳过犯错这一步。错误是你在黑暗中的光。错误揭示了需要被解决的问题。而问题，正是限制你思维的边界。</p><p>正如爱因斯坦所说：“你无法用制造问题的那种思维去解决这个问题。”</p><p>大多数人都跳过了这一部分。</p><p>他们以为自己想要一辆好车、一份舒适的工作、去世界各地旅行——但一旦真正拥有了这些东西，那种表面的光鲜很快就褪去了。</p><p>他们不断说服自己，这就是他们想要的生活，从不进化，从不追求更深层的东西，也永远得不到自己真正想要的东西。</p><p>也就是说，他们从未得到自己本性所渴望的东西，只是得到了自己自我（ego）所渴望的东西。</p><p>要想从生活中得到你真正想要的东西：</p><ul><li>追求你以为自己想要的东西</li><li>意识到你不想要什么</li><li>察觉到那个问题</li><li>与它共处，研究它，剖析它</li><li>拓展你的思维，去看到它背后的东西</li><li>解决问题，从而进化一个层次</li><li>重复这个过程，直到你触及生命本身的本质</li></ul><p>没有任何人能给你一条固定的路径来完成这件事。</p><p>别人可以通过建议和技巧给你指点方向，但他们无法代替你去行动、去思考、去解决问题。</p><p>你不知道自己从生活中想要什么，是因为你什么都还没尝试过。</p><p>你没有得到结果，是因为你还没有获得得到那些结果所需的技能。</p><p>你不知道什么是可能的，是因为你还没有让自己接触到那种能使之成为可能的视角。</p><p>你此刻想要的东西，到了明天，或者下个月，或者下一年，可能会完全不同。</p><p>没有什么能永远持续。意义存在于无穷无尽的解决问题之中，直到你钻得足够深，找到你真正在寻找的东西。</p><p>这很正常。这就是生活。</p><h2 id="生命的宏观循环——为什么你总感到迷失" tabindex="-1">生命的宏观循环——为什么你总感到迷失 <a class="header-anchor" href="#生命的宏观循环——为什么你总感到迷失" aria-label="Permalink to &quot;生命的宏观循环——为什么你总感到迷失&quot;">​</a></h2><p><img src="'+r+'" alt=""></p><p>你感到迷失，是因为你不知道接下来该做什么。</p><p>你不知道接下来该做什么，是因为你没有目标。</p><p>你没有（你真正在意的）目标，是因为你还没有意识到一个需要你全神贯注去解决的问题。</p><p>在你确定自己生活中想要解决的下一个问题之前，不要再费心去设定目标。</p><p>生活以章节、阶段和循环的形式展开。</p><p>你的人生是一个故事。</p><p>你的一年是一个故事。</p><p>你的一天是一个故事。</p><p>每一个故事都有一系列的目标、问题、高潮和低谷，它们可能会随着时间的流逝而反复出现。</p><p>生命存在一个宏观循环。</p><p>一旦你理解了它，你就能识别出自己正处于故事的哪个部分，意识到它的各个组成部分，并让自己的心平静下来，直到进入下一个阶段。</p><p>这个循环由3个阶段组成：</p><ol><li><strong>你感到迷失。</strong> 你不知道接下来该追求什么。你已经解决了一个问题，达成了一个目标，还以为那就是终点。</li><li><strong>你变得好奇。</strong> 你尝试各种不同的主题、兴趣和想法，直到你完全意识到自己想要解决的问题。</li><li><strong>你变得执着。</strong> 你潜入自己所选择的那片现实缝隙的更深处。你无法停止学习和为自己的目标而构建。</li></ol><p>当你感到迷失时，你必须强迫自己朝两个方向去实验：</p><p><strong>1）向内实验</strong></p><p>休息。小睡。写日记。散步。拥抱寂静。</p><p>观察并拆解你的想法。</p><p>试着捕捉一个机会的信号。</p><p>沿着你的思绪，追溯到一个根本性的问题。</p><p><strong>2）向外实验</strong></p><p>学习。阅读。刷内容。构建。尝试新事物。</p><p>重新聚焦到生活中真正重要的事情上。</p><p>健康、财富、关系、幸福。</p><p>尝试那些能把能量投入到一个目标上的方法。任何目标都行。</p><p>在实验阶段，你是在不断积累新的经验，直到你的下一个探索目标变得清晰可见。</p><p>就像电子游戏一样，你正处在一个任务尚未解锁的时刻，但你又没有别的任务可以追寻。你必须在黑暗中摸索，直到你在远处发现一支蜡烛。</p><p>注：不要把这称作“闪光物综合症”。</p><p>我今天的事业之所以可能存在，全靠我尝试并“失败”过7种不同的商业模式。回过头看，那些失败其实是技能叠加、解决问题以及扩大我对正确机会的感知面的时期。</p><p>现在，要明白，这个阶段没有时间限制。</p><p>它可能持续数周、数月，甚至数年。</p><p>你必须坚持下去，直到你积累了足够的眼界，能够停止四处试探，开始向深处扎根。</p><p>当你找到自己的执念之后，实验并不会因此停止。</p><p><strong>3）向下实验</strong></p><p>秘诀在于：尝试一切，直到你找到那一件让你无法离开的事情。然后，一旦它成为你生活中稀松平常的一部分，就重复这个过程。</p><p>当你找到那件事时，就深入钻进去。</p><p>尽你所能，把那个领域的一切都学到。</p><p>剖析所有的视角，避免对其中某一个变得教条化。</p><p>在营养学领域，从素食主义、生酮饮食、肉食主义、雷·皮特（Ray Peat）理论、灵活饮食等各种理念中汲取真理，直到你有足够的信心创造出属于自己的、更接近真理的一套体系。真理是一个过程，不是一条戒律。</p><p>在商业领域，从电商、自由职业、软件等各种模式中汲取真理，直到你总结出那些能为你自己的事业带来清晰认知的原则。</p><p>自我实验是彻底解决你的问题的唯一途径。</p><p>别人可以诊断你的问题并给你开出解决方案，但那种方式完全没考虑到，开方案的人与你之间在视角、目标和经验上的差异。</p><p><strong>4）向上实验</strong></p><p>坚持与迭代。</p><p>我假设，一旦你找到了自己的执念，你会想让它成为你生活中持续存在的一部分。</p><p>这意味着你必须从这个兴趣中赚取创造性收入。</p><p>在当今世界，这意味着：</p><ul><li>打造一个项目，传播出去，帮助他人解决他们的问题。</li><li>公开教学，以吸引那些有这些问题的人。</li><li>出售你的项目，这样你就能继续追求你的执念。</li><li>随着你从反馈中学到只能通过反馈才能学到的东西，不断改进你的项目。</li><li>当你达到只能通过商业才能达到的水平时，进化到一个新的项目。</li></ul><p>实现这一点的方法有很多。去实验吧。</p><p>但我可以自信地告诉你，通过我自己的实验，考虑到人性和未来的工作方式，创作者经济是“最真实”的一种可以遵循的模式。</p><h2 id="数字文艺复兴" tabindex="-1">数字文艺复兴 <a class="header-anchor" href="#数字文艺复兴" aria-label="Permalink to &quot;数字文艺复兴&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p>我们正生活在第二个黄金时代之中，而它属于那些珍视以下东西的人：</p><ul><li>自我教育</li><li>自我实验</li><li>多学科学习</li><li>数字杠杆</li><li>技能获取</li><li>构建属于自己的事物</li></ul><p>如果你想茁壮成长，就成为一个数字文艺复兴人。</p><p>以下是你该做的事：</p><h3 id="加入这个新社会" tabindex="-1">加入这个新社会 <a class="header-anchor" href="#加入这个新社会" aria-label="Permalink to &quot;加入这个新社会&quot;">​</a></h3><p>社交媒体不只是你手机上的一个应用程序。</p><p>它是一所去中心化的公立学校、一个市场、一个讲台——但只属于那些珍视个人责任的人。你并非被迫成为这个社会的一部分，正因为如此，它才如此重要。</p><p>你不再需要创业资本来开启一份事业。</p><p>你不再需要招聘网站来找到一份职业。</p><p>你不再需要出版商来推出一本书。</p><p>你不再需要唱片公司来制作音乐。</p><p>你不再需要正规教育才能成为专家。</p><p>你不再需要宗教机构来为你灌注意义。</p><p>对学习、意义和赚钱的集中式权威把控，只属于那些还在沉睡中的人。</p><p>你所需要的只是一个网络连接、一个社交媒体账户，以及去教学、去失败、去改进、去坚持的勇气。</p><p>我在<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">《2小时写作者》(2 Hour Writer)</a>和<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">《数字经济学》(Digital Economics)</a>中教授这些内容。</p><h3 id="让自己变得有价值" tabindex="-1">让自己变得有价值 <a class="header-anchor" href="#让自己变得有价值" aria-label="Permalink to &quot;让自己变得有价值&quot;">​</a></h3><p>每个人都告诉你要变得有价值，但没有人告诉你价值到底是什么。</p><p>价值，是你做什么、为什么做、如何做，以及谁从这个等式中受益之间的关系。</p><p>价值由4个部分组成。</p><ul><li><strong>问题</strong> —— 一种未被解决时会带来痛苦的局限或挑战。</li><li><strong>解决方案</strong> —— 一个有影响力的最终结果，能让接受者超越那个问题，获得进化。</li><li><strong>清晰度</strong> —— 一个能孕育知识、技能和认知的创造性系统，用以弥合问题与解决方案之间的差距。</li><li><strong>人</strong> —— 受这个问题困扰、能从解决方案中受益、并且已经准备好接受这份清晰度去行动的人的数量。</li></ul><p>价值是经验的交换。</p><p>价值是你故事所产生的影响。</p><p>所以，为了赚取创造性收入，我们的工作就是通过解决那些阻碍我们进化的问题来获得经验，并把凝练后的智慧，传授给那些已经准备好接受它的人。</p><p><strong>1）用反向愿景揭示问题</strong></p><p>了解你不想要什么——来自经验——要比了解你想要什么——来自想象——容易得多。</p><p>所以，为你的未来创建一个反向愿景（anti-vision）。</p><p>保持一份持续记录的笔记，随着你对生活的观察不断添加内容：</p><ul><li>你<strong>不</strong>想成为什么样子？</li><li>你<strong>不</strong>想有什么样的感受？</li><li>你<strong>最糟糕</strong>的一天是什么样子的？</li><li>你<strong>不</strong>希望你的朋友、客户、伴侣和同事具备什么品质？</li><li>多少钱<strong>不足以</strong>维持生存？</li><li>以上这一切是如何渗透进你生活的每个领域，阻止你做你想做的事的？</li></ul><p>抓住真正重要的东西。健康、财富、关系和幸福。这些才是商业中永恒不变的市场。如果你能在这些领域内为某个问题打造一个创造性的解决方案，那你靠自己的经验谋生就不成问题。</p><p><strong>2）用正向愿景确定解决方案</strong></p><p>现在你手头有大量的问题，可以逐步解决它们来提升你的价值。</p><p>挑一个，解决它，再进行下一个。意义不在于达成某个目标，而在于解决那一连串无穷无尽的问题，正是这些问题把你拉向现实本质的更深处。</p><p>现在，为了增强你解决它的渴望，为你理想的未来创建一个愿景。</p><p>把你为反愿景列出的每一项都写出其反面。</p><p>把这个当作一个最小可行愿景(Minimum Viable Vision)。你会随着时间不断补充它。随着你的成长,你想要的东西也会改变。</p><p><strong>3) 为了清晰而学习和构建</strong></p><p>不是为了构建而学习,而是为了学习而构建。</p><p>你已经选定了一个你想在生活中解决的问题。这可能与健身、财务、自由,或任何其他阻碍你过上你想要的生活的东西有关。</p><p>带着这个问题,把注意力聚焦在一个大目标上。</p><p>但要记住,目标一开始并不具有吸引力。你可能根本不在乎这个目标。</p><p>你必须持续向这个目标投入精力,直到你觉得不去实现它就是在浪费资源。你的目标必须足够长时间地框定你的视角,让你能积累出足够继续追求它的理由。</p><p>你无法在一天之内建立起一套内在的哲学观。</p><p>你要通过对话、阅读、倾听,以及不断筛选现实,直到你积累了足够多的“为什么”,才能建立起这种哲学观,让自己对此负责。</p><p>你会失败。这是识别你接下来需要学什么的唯一方式。</p><p>当你确实失败时,立刻把它重新定义为一个知识缺口。</p><p>用这次失败作为一个新的框架,去筛选你的经历,寻找答案。</p><p><strong>4) 用你的故事吸引人</strong></p><p>做一个失败者。</p><p>把项目发布出去,面对一片寂静无声。发表你的想法,却被人骂作傻子。启动这个事业,眼看着人们批评你最初的举动。</p><p>每个人都经历过这些。你不是特例。</p><p>不断投资你的失败组合,直到你有能力承受成功。</p><p>你的失败组合,就是你的故事。</p><p>就像一部电影,人们对低谷的兴趣往往超过对高潮的兴趣。</p><p>当你拥有解决生活中某个问题的方案时,你就会把人和利润吸引到自己身边。</p><h3 id="分发你的价值" tabindex="-1">分发你的价值 <a class="header-anchor" href="#分发你的价值" aria-label="Permalink to &quot;分发你的价值&quot;">​</a></h3><p>最伟大的技能是写作,因为:</p><ul><li>它迫使你把自己的价值清晰地表达出来</li><li>它是所有媒介的基础</li><li>它可以被重新用于任何其他媒介形式</li><li>你获得的任何其他技能都会增强它</li><li>它带来巨大的思维清晰度</li></ul><p>学会写作。</p><p>你需要一些时间才能意识到,写作是杠杆最高的工作。</p><p>你必须把你的价值提炼成有影响力的想法,让它们免费住进别人的脑子里,影响他们的思想和行为。</p><p>你要通过持续且不断迭代的努力,写邮件、写内容、写指南、写产品来做到这一点。</p><p>写作是沟通的基础。</p><p>沟通是你分发价值的方式。</p><p>分发价值是你吸引人的方式。</p><p>如果你不能吸引人,你就永远无法在价值交换过程中拥有另一方。</p><p>这不是那种别人为你完成机械任务而付你薪水的工作,那种工作终将被取代。</p><p>这是一种目标(purpose),必须被另一个人共同分享,才能赚取创造性收入。</p><p>我在之前的信里已经讨论过这个话题,请去搜索它们,或者我们会在<a href="https://university.kortex.co/" target="_blank" rel="noreferrer">Kortex 大学(Kortex University),16 周内带你成为一名整合者(synthesizer)</a>中一步步带你走完整个过程。</p><p>感谢你阅读这封信。</p><p>希望它对你有帮助。</p><p>Dan</p><hr><p><a href="/en/letters/most-people-are-lost-how-to-ruin-your-life-fast">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',164))])}const P=l(u,[["render",g]]);export{q as __pageData,P as default};
